/** Liste des noms d'icônes disponibles. */
function icons_catalogue(): array
{
    return array_keys(icons_paths());
}

function icon(string $name, int $size = 20, string $class = ''): string
{
    $paths = icons_paths();
    if (!isset($paths[$name])) {
        return '';
    }
    $cls = $class !== '' ? ' class="' . e($class) . '"' : '';
    return '<svg' . $cls . ' width="' . $size . '" height="' . $size . '" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">' . $paths[$name] . '</svg>';
}
